(3980930, 566142, 70, '<td valign="top">Not a fan of the selective desat but nice photo otherwise.</td>', 'Not a fan of the selective desat but nice photo otherwise.', '2007-08-08 12:55:55.000000', NULL, 1),
(3980935, 563661, 70, '<td valign="top">To be honest, I think I would have liked this better without the flowers. The harshness of their dark/bright colors interrupts an otherwise soothing image. Nice lighting on the bottles, though.</td>', 'To be honest, I think I would have liked this better without the flowers. The harshness of their dark/bright colors interrupts an otherwise soothing image. Nice lighting on the bottles, though.', '2007-08-08 12:57:34.000000', NULL, 1),
(3980941, 566648, 70, '<td valign="top">Sweet. Totally summer.</td>', 'Sweet. Totally summer.', '2007-08-08 12:58:24.000000', NULL, 1),
(3980953, 566880, 70, '<td valign="top">With the exception of the bar across the top, this is completely gorgeous.</td>', 'With the exception of the bar across the top, this is completely gorgeous.', '2007-08-08 13:02:48.000000', NULL, 1),
(3980968, 566231, 70, '<td valign="top">I prefer to think my soul is not quite so wrinkly and rutted with larger portions of light and color. But an interesting image anyway. :)</td>', 'I prefer to think my soul is not quite so wrinkly and rutted with larger portions of light and color. But an interesting image anyway. :)', '2007-08-08 13:07:08.000000', NULL, 1),
