(3981728, 566097, 31637, '<td valign="top">GREAT ! 10</td>', 'GREAT ! 10', '2007-08-08 18:00:24.000000', NULL, 1),
(3981730, 566529, 31637, '<td valign="top">I think the shadow of the person is enough here, the other shadows are very distracting,the soft morninglight is awesome here, the texture of the street as well, this could have won if those other shadows..</td>', 'I think the shadow of the person is enough here, the other shadows are very distracting,the soft morninglight is awesome here, the texture of the street as well, this could have won if those other shadows..', '2007-08-08 18:01:15.000000', NULL, 1),
(3981805, 566585, 41098, '<td valign="top">I ranked this the highest - for crispness, creativity and overall great shot. I love the broken glasses, the use of the lighting - great work</td>', 'I ranked this the highest - for crispness, creativity and overall great shot. I love the broken glasses, the use of the lighting - great work', '2007-08-08 18:32:19.000000', NULL, 1),
(3981806, 565625, 41098, '<td valign="top">Very good use of shadows - you met the challenge very well.</td>', 'Very good use of shadows - you met the challenge very well.', '2007-08-08 18:32:41.000000', NULL, 1),
