(3981820, 566694, 41098, '<td valign="top">Cut the large black object from the right and this would have been great - it just stole the show over there. :(</td>', 'Cut the large black object from the right and this would have been great - it just stole the show over there. :(', '2007-08-08 18:36:19.000000', NULL, 1),
