(3981823, 566548, 41098, '<td valign="top">Shadows???</td>', 'Shadows???', '2007-08-08 18:36:47.000000', NULL, 1),
(3981851, 566781, 82438, '<td valign="top">The composition of this photo is AMAZING especially with the alternating shadows, where something in the foreground is shaded against a sunlit background and vise versa. I think the choice of black and white is perfect, making the contrast that much more intense and really capturing the shadows in a way that most people might not have even thought of.</td>', 'The composition of this photo is AMAZING especially with the alternating shadows, where something in the foreground is shaded against a sunlit background and vise versa. I think the choice of black and white is perfect, making the contrast that much more intense and really capturing the shadows in a way that most people might not have even thought of.', '2007-08-08 18:52:24.000000', NULL, 1),
(3982002, 566391, 70103, '<td valign="top">I don''t quite see the shadows here...</td>', 'I don''t quite see the shadows here...', '2007-08-08 19:44:18.000000', NULL, 1),
(3982018, 566529, 70103, '<td valign="top">I would''ve liked it better if you cropped the other shadows because they distracts us from the main subject</td>', 'I would''ve liked it better if you cropped the other shadows because they distracts us from the main subject', '2007-08-08 19:48:15.000000', NULL, 1),
