(3982397, 566873, 70514, '<td valign="top">Wow!  Very cool and nice composition.</td>', 'Wow!  Very cool and nice composition.', '2007-08-08 22:32:14.000000', NULL, 1),
(3982434, 566672, 70514, '<td valign="top">I love the solitude of this.  The broken glass (I think that''s what it is) is such an added bonus.  The composition and processing is nice, also.  Great expression of raw emotion from the model.</td>', 'I love the solitude of this.  The broken glass (I think that''s what it is) is such an added bonus.  The composition and processing is nice, also.  Great expression of raw emotion from the model.', '2007-08-08 22:39:48.000000', NULL, 1),
(3982455, 566097, 70514, '<td valign="top">Very cool alter ego!  Great composition.</td>', 'Very cool alter ego!  Great composition.', '2007-08-08 22:45:51.000000', NULL, 1),
(3982457, 565906, 70514, '<td valign="top">Great dof and perspective.  I love the colors and lighting.</td>', 'Great dof and perspective.  I love the colors and lighting.', '2007-08-08 22:46:33.000000', NULL, 1),
(3982460, 566467, 70514, '<td valign="top">I really like this and can''t say why.  It''s original, and the shadow is unmistakable.  Very evocative, for me.</td>', 'I really like this and can''t say why.  It''s original, and the shadow is unmistakable.  Very evocative, for me.', '2007-08-08 22:47:20.000000', NULL, 1),
(3982484, 566315, 70514, '<td valign="top">Great crisp shadows and nice composition and lighting.</td>', 'Great crisp shadows and nice composition and lighting.', '2007-08-08 22:54:46.000000', NULL, 1),
(3982493, 566809, 70514, '<td valign="top">Nice undies ;)  I actually really like this, very whimsical, and emotive.  Great lighting and colors.  (and the extra clothes just add to it all!)</td>', 'Nice undies ;)  I actually really like this, very whimsical, and emotive.  Great lighting and colors.  (and the extra clothes just add to it all!)', '2007-08-08 22:56:27.000000', NULL, 1),
