(3988943, 566601, 48697, '<td valign="top">This is a very nice shot! Lovely smooth transition from white to black on the egg. I like the composition and the detail in the textures on the egg and the table. Nicly done!</td>', 'This is a very nice shot! Lovely smooth transition from white to black on the egg. I like the composition and the detail in the textures on the egg and the table. Nicly done!', '2007-08-11 13:46:51.000000', NULL, 1),
(3988946, 566577, 48697, '<td valign="top">I like  how the shadows creep out towards the viewer.  I think that a tighter crop so the tree in the lower right is out might have helped the composition a bit. I also feel that this, a nice shot, could have been very dynamic in a b&amp;w as well!</td>', 'I like  how the shadows creep out towards the viewer.  I think that a tighter crop so the tree in the lower right is out might have helped the composition a bit. I also feel that this, a nice shot, could have been very dynamic in a b&w as well!', '2007-08-11 13:49:15.000000', NULL, 1),
(3988948, 566590, 48697, '<td valign="top">Cool perspective and I love the distortion. Cute model and good use of shadows!</td>', 'Cool perspective and I love the distortion. Cute model and good use of shadows!', '2007-08-11 13:50:32.000000', NULL, 1),
(3988954, 566640, 68769, '<td valign="top">I think concentrating the attention to the rear shadow would have more impact, it seemed to be sharper. 6</td>', 'I think concentrating the attention to the rear shadow would have more impact, it seemed to be sharper. 6', '2007-08-11 13:56:14.000000', NULL, 1),
