(3989862, 564356, 57032, '<td valign="top">Good colour, but the exposure is a bit dark. Seems it was just done:<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=564369" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/719/thumb/564369.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/719/thumb/564369.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/719/thumb/564369.jpg"/></a></td>', 'Good colour, but the exposure is a bit dark. Seems it was just done: ', '2007-08-12 01:27:50.000000', NULL, 1),
(3989998, 566601, 74371, '<td valign="top">Extremely nice! I like the total evenness of the shadows...all being of equal depth of color and all. Extremely well focussed and aligned in the photograph. Great job!! (8)</td>', 'Extremely nice! I like the total evenness of the shadows...all being of equal depth of color and all. Extremely well focussed and aligned in the photograph. Great job!! (8)', '2007-08-12 02:37:09.000000', NULL, 1),
(3990005, 566781, 74371, '<td valign="top">A beautiful shot, but to me... the contrast is just too harsh for the shot. That is the only complaint I have. Good job!  (7)</td>', 'A beautiful shot, but to me... the contrast is just too harsh for the shot. That is the only complaint I have. Good job!  (7)', '2007-08-12 02:39:13.000000', NULL, 1),
(3990007, 565602, 74371, '<td valign="top">Not sure what this is so cannot be to impressed. Sorry! It ''appears'' to be very out of focus. I assume by "Gust" that these may be clouds but you should try and have something as a point of focus to give us a better idea. I do like the colors though! (5)</td>', 'Not sure what this is so cannot be to impressed. Sorry! It ''appears'' to be very out of focus. I assume by "Gust" that these may be clouds but you should try and have something as a point of focus to give us a better idea. I do like the colors though! (5)', '2007-08-12 02:43:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3990008, 566070, 74371, '<td valign="top">Fun and pleasing!! Way to go!!! (8)</td>', 'Fun and pleasing!! Way to go!!! (8)', '2007-08-12 02:44:11.000000', NULL, 1),
(3990017, 566548, 74371, '<td valign="top">Extremely well taken action shot! The focus is perfect... even the tires show focus  with action involved. Wish i could claim this as my entry!! Sigh!!<br/> <br/>Would love to see the other shots you took while getting this spectacular one!! (9)</td>', 'Extremely well taken action shot! The focus is perfect... even the tires show focus  with action involved. Wish i could claim this as my entry!! Sigh!! Would love to see the other shots you took while getting this spectacular one!! (9)', '2007-08-12 02:50:54.000000', NULL, 1),
(3990019, 566810, 74371, '<td valign="top">I love this shot!! It appears to be in focus (chuckle) but is most pleasing to look at. (8)<br/> <br/>Uh... I wouldn''t show this to many NON-photographers. You might get accused of having a humongous bootie! :)</td>', 'I love this shot!! It appears to be in focus (chuckle) but is most pleasing to look at. (8) Uh... I wouldn''t show this to many NON-photographers. You might get accused of having a humongous bootie! :)', '2007-08-12 02:54:48.000000', NULL, 1),
(3990020, 566763, 74371, '<td valign="top">Impressive!</td>', 'Impressive!', '2007-08-12 02:55:24.000000', NULL, 1),
(3990023, 566307, 74371, '<td valign="top">Excellent!! Besides hitting the Challenge right on... this is an exquisite photo! Might have been great in color also, but I doubt if the "backup players" would have been so prominent!! Way to go!! (9)</td>', 'Excellent!! Besides hitting the Challenge right on... this is an exquisite photo! Might have been great in color also, but I doubt if the "backup players" would have been so prominent!! Way to go!! (9)', '2007-08-12 02:57:50.000000', NULL, 1),
(3990029, 566687, 74371, '<td valign="top">IR Photography should be outlawed! It is just too cool!! :) <br/> <br/>Nice shot!</td>', 'IR Photography should be outlawed! It is just too cool!! :)  Nice shot!', '2007-08-12 03:06:45.000000', NULL, 1),
(3990035, 566315, 74371, '<td valign="top">Wonderful!!! Always having been a wannabe jazz saxophone player...I love this shot! Way to go!!  (8)</td>', 'Wonderful!!! Always having been a wannabe jazz saxophone player...I love this shot! Way to go!!  (8)', '2007-08-12 03:12:12.000000', NULL, 1),
(3990038, 566884, 74371, '<td valign="top">Wonderful shot...just wish it was a little lighter. Would''ve liked to have been able to see more of the head. Otherwise...good job! (8)</td>', 'Wonderful shot...just wish it was a little lighter. Would''ve liked to have been able to see more of the head. Otherwise...good job! (8)', '2007-08-12 03:20:49.000000', NULL, 1),
