(3990056, 566743, 52549, '<td valign="top">This is really interestingly done. The b/w is great.</td>', 'This is really interestingly done. The b/w is great.', '2007-08-12 03:40:48.000000', NULL, 1),
(3990057, 565625, 52549, '<td valign="top">Very cool shot.</td>', 'Very cool shot.', '2007-08-12 03:41:40.000000', NULL, 1),
(3990059, 566598, 52549, '<td valign="top">Great shot. Definitely top 10.</td>', 'Great shot. Definitely top 10.', '2007-08-12 03:42:45.000000', NULL, 1),
(3990060, 566601, 52549, '<td valign="top">I love the clarity and tones of this. Top 3 in my book.</td>', 'I love the clarity and tones of this. Top 3 in my book.', '2007-08-12 03:43:26.000000', NULL, 1),
(3990063, 566231, 42495, '<td valign="top">Great contrast; really like the title.</td>', 'Great contrast; really like the title.', '2007-08-12 03:45:13.000000', NULL, 1),
